    async fn upstream_fixture(body: &'static str) -> (String, Arc<AtomicUsize>) {
        upstream_bytes_fixture(body.as_bytes().to_vec(), "application/json").await
    }

    async fn upstream_bytes_fixture(
        body: Vec<u8>,
        content_type: &'static str,
    ) -> (String, Arc<AtomicUsize>) {
        upstream_bytes_fixture_with_optional_content_type(body, Some(content_type)).await
    }

    async fn upstream_bytes_fixture_with_optional_content_type(
        body: Vec<u8>,
        content_type: Option<&'static str>,
    ) -> (String, Arc<AtomicUsize>) {
        upstream_bytes_fixture_with_status(body, content_type, 200).await
    }

    /// Read one whole request off `stream` before answering it.
    ///
    /// Not cosmetic. A fixture that answers with bytes still sitting
    /// unread in its receive queue turns its own close into an RST, and
    /// the RST arrives at the gateway between the response headers and
    /// the response body: the relay's body read then fails with
    /// `ConnectionReset` and the test sees a transport error instead of
    /// the 200 the upstream actually wrote. The old single 4096-byte
    /// read was under every request any test sent until one carried a
    /// body larger than that (WOR-2616's inside-the-cap forward).
    async fn drain_upstream_request(stream: &mut tokio::net::TcpStream) {
        let mut request = Vec::new();
        let mut chunk = [0_u8; 4096];
        loop {
            let read = match stream.read(&mut chunk).await {
                Ok(0) => return,
                Ok(read) => read,
                Err(_) => return,
            };
            request.extend_from_slice(&chunk[..read]);
            let Some(headers_end) = request.windows(4).position(|window| window == b"\r\n\r\n")
            else {
                continue;
            };
            let headers = String::from_utf8_lossy(&request[..headers_end]);
            let chunked = headers.lines().any(|line| {
                line.split_once(':').is_some_and(|(name, value)| {
                    name.eq_ignore_ascii_case("transfer-encoding")
                        && value.to_ascii_lowercase().contains("chunked")
                })
            });
            if chunked {
                // Chunked uploads end with the zero-length chunk; a
                // fixture that stopped at the headers would leave the
                // whole body unread.
                while !request.ends_with(b"0\r\n\r\n") {
                    match stream.read(&mut chunk).await {
                        Ok(0) | Err(_) => return,
                        Ok(read) => request.extend_from_slice(&chunk[..read]),
                    }
                }
                return;
            }
            let declared = headers
                .lines()
                .find_map(|line| {
                    let (name, value) = line.split_once(':')?;
                    name.eq_ignore_ascii_case("content-length")
                        .then(|| value.trim().parse::<usize>().ok())
                        .flatten()
                })
                .unwrap_or(0);
            let expected = headers_end + 4 + declared;
            while request.len() < expected {
                match stream.read(&mut chunk).await {
                    Ok(0) | Err(_) => return,
                    Ok(read) => request.extend_from_slice(&chunk[..read]),
                }
            }
            return;
        }
    }

    async fn upstream_bytes_fixture_with_status(
        body: Vec<u8>,
        content_type: Option<&'static str>,
        status: u16,
    ) -> (String, Arc<AtomicUsize>) {
        slow_upstream_fixture_with_status(body, content_type, status, Duration::ZERO).await
    }

    async fn slow_upstream_fixture(body: Vec<u8>, delay: Duration) -> (String, Arc<AtomicUsize>) {
        slow_upstream_fixture_with_status(body, Some("application/json"), 200, delay).await
    }

    async fn slow_upstream_fixture_with_status(
        body: Vec<u8>,
        content_type: Option<&'static str>,
        status: u16,
        delay: Duration,
    ) -> (String, Arc<AtomicUsize>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind upstream fixture");
        let address = listener.local_addr().expect("upstream address");
        let hits = Arc::new(AtomicUsize::new(0));
        let observed = Arc::clone(&hits);
        tokio::spawn(async move {
            let (mut stream, _) = listener.accept().await.expect("accept upstream request");
            observed.fetch_add(1, Ordering::SeqCst);
            drain_upstream_request(&mut stream).await;
            if !delay.is_zero() {
                tokio::time::sleep(delay).await;
            }
            let content_type_header = content_type
                .map(|content_type| format!("content-type: {content_type}\r\n"))
                .unwrap_or_default();
            let response = format!(
                "HTTP/1.1 {status} Fixture\r\n{content_type_header}content-length: {}\r\nconnection: close\r\n\r\n",
                body.len()
            );
            stream
                .write_all(response.as_bytes())
                .await
                .expect("write upstream response");
            stream
                .write_all(&body)
                .await
                .expect("write upstream response body");
        });
        (format!("http://{address}/v1"), hits)
    }

    // --- WOR-2690: cancel the provider call when the client leaves ---
    //
    // Nested rather than loose in the parent module, which is named for
    // external guardrails and has long since stopped being only about
    // them. The qualifier is what a CI failure line shows, so these read
    // as what they are.
    /// WOR-2622: `stream_include_usage`, the opt-in that asks an
    /// OpenAI-compatible provider for a terminal usage frame.
    ///
    /// Six unit tests over `apply_stream_include_usage` itself, one per
    /// gate, rather than dispatches: what is under test is which
    /// requests get the field, and a live provider fixture would answer
    /// that no more precisely.
    mod stream_include_usage_tests {
        use crate::server::ai_dispatch::apply_stream_include_usage;

        fn config(include_usage: bool, provider_type: &str) -> sbproxy_ai::AiHandlerConfig {
            sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
                "providers": [{
                    "name": "upstream",
                    "provider_type": provider_type,
                    "base_url": "http://127.0.0.1:1/v1",
                    "allow_private_base_url": true,
                    "api_key": "fixture-key"
                }],
                "stream_include_usage": include_usage
            }))
            .expect("include-usage fixture config")
        }

        fn streaming_body() -> serde_json::Value {
            serde_json::json!({
                "model": "gpt-4o-mini",
                "stream": true,
                "messages": [{"role": "user", "content": "hello"}]
            })
        }

        /// The default has to leave the caller's body alone: with the
        /// field injected the provider appends a terminal chunk whose
        /// `choices` is `[]`, and a client that indexes `choices[0]`
        /// throws on it.
        #[test]
        fn the_field_is_not_injected_until_an_operator_asks() {
            let config = config(false, "openai");
            let mut body = streaming_body();
            assert!(!apply_stream_include_usage(
                &config,
                &config.providers[0],
                &sbproxy_ai::handler::AiSurface::ChatCompletions,
                &mut body,
            ));
            assert!(body.get("stream_options").is_none());
        }

        #[test]
        fn an_opted_in_openai_stream_asks_for_the_usage_frame() {
            let config = config(true, "openai");
            let mut body = streaming_body();
            assert!(apply_stream_include_usage(
                &config,
                &config.providers[0],
                &sbproxy_ai::handler::AiSurface::ChatCompletions,
                &mut body,
            ));
            assert_eq!(
                body["stream_options"],
                serde_json::json!({"include_usage": true})
            );
        }

        /// Anthropic, Vertex, Bedrock, Cohere and Ollama have no
        /// `stream_options`, and several OpenAI-compatible servers 400 on
        /// an unknown top-level key, so a blanket injection would turn a
        /// working stream into a hard failure.
        #[test]
        fn a_provider_without_stream_options_is_left_alone() {
            let config = config(true, "anthropic");
            let mut body = streaming_body();
            assert!(!apply_stream_include_usage(
                &config,
                &config.providers[0],
                &sbproxy_ai::handler::AiSurface::ChatCompletions,
                &mut body,
            ));
            assert!(body.get("stream_options").is_none());
        }

        #[test]
        fn a_caller_that_set_stream_options_keeps_what_it_asked_for() {
            let config = config(true, "openai");
            let mut body = streaming_body();
            body["stream_options"] = serde_json::json!({"include_usage": false});
            assert!(!apply_stream_include_usage(
                &config,
                &config.providers[0],
                &sbproxy_ai::handler::AiSurface::ChatCompletions,
                &mut body,
            ));
            assert_eq!(
                body["stream_options"],
                serde_json::json!({"include_usage": false})
            );
        }

        #[test]
        fn a_unary_request_is_left_alone() {
            let config = config(true, "openai");
            let mut body = streaming_body();
            body["stream"] = serde_json::Value::Bool(false);
            assert!(!apply_stream_include_usage(
                &config,
                &config.providers[0],
                &sbproxy_ai::handler::AiSurface::ChatCompletions,
                &mut body,
            ));
            assert!(body.get("stream_options").is_none());
        }

        /// Embeddings and the image surfaces have no `stream_options`
        /// either, and the injection runs on the per-attempt body for
        /// every surface the dispatcher handles.
        #[test]
        fn a_non_chat_surface_is_left_alone() {
            let config = config(true, "openai");
            let mut body = streaming_body();
            assert!(!apply_stream_include_usage(
                &config,
                &config.providers[0],
                &sbproxy_ai::handler::AiSurface::Embeddings,
                &mut body,
            ));
            assert!(body.get("stream_options").is_none());
        }
    }

    /// WOR-2622: what a streamed response is billed, and what its
    /// receipt says, when the stream does not end the way the happy
    /// path assumes.
    ///
    /// Every test here drives a whole `handle_ai_proxy` dispatch over a
    /// live loopback socket pair against a provider fixture that speaks
    /// real SSE, because the thing under test is the seam between the
    /// relay's exits and the settlement, and an in-process call to the
    /// relay would not have a downstream write that can fail.
    mod stream_usage_finalizer_tests {
        use super::*;

        /// One SSE frame, already wrapped in its `data:` envelope.
        fn sse(payload: &str) -> String {
            format!("data: {payload}\n\n")
        }

        /// A content delta carrying `text`.
        fn content_frame(text: &str) -> String {
            sse(&format!(
                r#"{{"choices":[{{"index":0,"delta":{{"content":"{text}"}}}}]}}"#
            ))
        }

        /// The provider's terminal usage frame.
        fn usage_frame(prompt: u64, completion: u64) -> String {
            sse(&format!(
                r#"{{"choices":[],"usage":{{"prompt_tokens":{prompt},"completion_tokens":{completion}}}}}"#
            ))
        }

        /// What a streaming provider fixture saw happen to its
        /// connection.
        #[derive(Debug, PartialEq, Eq)]
        enum StreamUpstreamOutcome {
            /// The gateway stopped reading before the fixture ran out of
            /// frames, which is the generation not being paid for past
            /// the point the client left.
            Abandoned,
            /// The fixture wrote everything it had and closed.
            Completed,
        }

        struct StreamUpstream {
            /// Fires once the fixture has written `announce_after`
            /// frames, so a test can act at a known point in the stream.
            announced: tokio::sync::oneshot::Receiver<()>,
            outcome: tokio::task::JoinHandle<StreamUpstreamOutcome>,
        }

        /// A provider that streams `frames` and then, if `filler` is
        /// non-zero, keeps emitting content frames until one of its
        /// writes fails.
        ///
        /// The filler is what makes a downstream disconnect observable:
        /// a socket absorbs the first few kilobytes whatever the peer
        /// does, so a relay only learns the client is gone by trying to
        /// write after the reset has landed. `Abandoned` therefore means
        /// the gateway really did stop consuming this generation.
        async fn streaming_upstream_fixture(
            frames: Vec<String>,
            announce_after: usize,
            filler: usize,
        ) -> (String, StreamUpstream) {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
                .await
                .expect("bind streaming upstream fixture");
            let address = listener.local_addr().expect("streaming upstream address");
            let (announce, announced) = tokio::sync::oneshot::channel();
            let outcome = tokio::spawn(async move {
                let (mut stream, _) = listener.accept().await.expect("accept upstream request");
                drain_upstream_request(&mut stream).await;
                let header = "HTTP/1.1 200 Fixture\r\ncontent-type: text/event-stream\r\ncache-control: no-cache\r\nconnection: close\r\n\r\n";
                if stream.write_all(header.as_bytes()).await.is_err() {
                    return StreamUpstreamOutcome::Abandoned;
                }
                let mut announce = Some(announce);
                for (index, frame) in frames.iter().enumerate() {
                    if stream.write_all(frame.as_bytes()).await.is_err() {
                        return StreamUpstreamOutcome::Abandoned;
                    }
                    let _ = stream.flush().await;
                    if index + 1 == announce_after {
                        if let Some(tx) = announce.take() {
                            let _ = tx.send(());
                        }
                    }
                    tokio::time::sleep(Duration::from_millis(2)).await;
                }
                if let Some(tx) = announce.take() {
                    let _ = tx.send(());
                }
                for _ in 0..filler {
                    let frame = content_frame("filler");
                    if stream.write_all(frame.as_bytes()).await.is_err() {
                        return StreamUpstreamOutcome::Abandoned;
                    }
                    if stream.flush().await.is_err() {
                        return StreamUpstreamOutcome::Abandoned;
                    }
                    tokio::time::sleep(Duration::from_millis(2)).await;
                }
                let _ = stream.shutdown().await;
                if filler > 0 {
                    // The fixture ran its whole filler budget without a
                    // failed write, so the gateway was still relaying.
                    StreamUpstreamOutcome::Completed
                } else {
                    StreamUpstreamOutcome::Completed
                }
            });
            (
                format!("http://{address}/v1"),
                StreamUpstream { announced, outcome },
            )
        }

        /// Starts of SSE data frames carrying a JSON payload in a
        /// relayed response.
        ///
        /// Starts, not completed frames: this matches the `data:`
        /// prefix and the byte that opens its JSON payload, and never
        /// looks for the terminating blank line, so a caller waiting on
        /// `n` has `n - 1` frames delivered whole and one begun.
        /// Callers want a lower bound on delivered content and get one;
        /// the caller below needs 9 completion tokens and waits for
        /// about 70.
        ///
        /// `data: [DONE]` and the response headers are deliberately not
        /// counted: a caller waiting on this wants frames the usage
        /// estimator can draw completion text out of.
        fn delivered_sse_frames(buffer: &[u8]) -> usize {
            // Spelled as a code point rather than written out.
            // `scripts/scan-pub-item-usage.py` brace-counts `#[cfg(test)]`
            // regions, so an unbalanced brace inside a literal here
            // extends the region it computes past the end of this module
            // and mis-files the production references below it as test
            // consumers. `sbproxy_ai::model_group::routing_name` was the
            // one that moved.
            const JSON_OPEN: u8 = 0x7b;
            buffer
                .windows(7)
                .filter(|window| window.starts_with(b"data: ") && window[6] == JSON_OPEN)
                .count()
        }

        /// A downstream client that reads the streamed response and
        /// breaks its connection when the test says so.
        ///
        /// `SO_LINGER` at zero turns the close into an RST rather than a
        /// FIN, which is the shape a relay's next write actually fails
        /// on. A half-close would leave the gateway writing into a
        /// socket that is still reading, which is the case WOR-2690
        /// deliberately does not treat as a departure.
        async fn streaming_downstream_session(
            body: serde_json::Value,
        ) -> (Session, tokio::sync::oneshot::Sender<()>, DownstreamClient) {
            let (session, close, client, _delivered) =
                streaming_downstream_session_watching_frames(body, None).await;
            (session, close, client)
        }

        /// The same client, plus a signal that fires once it has read
        /// `announce_frames` data frames off the relayed response.
        ///
        /// This is the happens-before edge a test needs before it can
        /// drop a dispatch mid-stream. The bytes the client counts are
        /// the relay's own downstream writes, and the relay only makes
        /// them from inside `relay_ai_stream`, which is downstream of
        /// the point where the settle guard is armed. Reading them is
        /// therefore proof that the guard exists.
        ///
        /// A wall-clock deadline is not that proof and cannot be made
        /// into one by raising it. The request side of a dispatch builds
        /// the model's BPE table on the first call in a process, which
        /// is a synchronous block no timer can preempt: on a loaded
        /// machine the whole deadline can pass before the relay exists
        /// at all, and the test then reads the unarmed `None` and
        /// reports a settlement failure that never happened.
        ///
        /// `None` counts nothing and never fires, which is what every
        /// caller that does not need the edge wants.
        async fn streaming_downstream_session_watching_frames(
            body: serde_json::Value,
            announce_frames: Option<usize>,
        ) -> (
            Session,
            tokio::sync::oneshot::Sender<()>,
            DownstreamClient,
            tokio::sync::oneshot::Receiver<()>,
        ) {
            let body = serde_json::to_vec(&body).expect("request JSON");
            let mut wire = format!(
                "POST /v1/chat/completions HTTP/1.1\r\nHost: ai.test\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                body.len()
            )
            .into_bytes();
            wire.extend_from_slice(&body);

            let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
                .await
                .expect("bind downstream fixture");
            let address = listener.local_addr().expect("downstream address");
            let (close, mut closed) = tokio::sync::oneshot::channel::<()>();
            let (announce, delivered) = tokio::sync::oneshot::channel::<()>();
            let mut client = DownstreamClient::new(tokio::spawn(async move {
                let mut announce = announce_frames.map(|wanted| (wanted, announce));
                let mut stream = tokio::net::TcpStream::connect(address)
                    .await
                    .expect("connect downstream fixture");
                stream.write_all(&wire).await.expect("write request");
                let mut response = Vec::new();
                let mut chunk = [0_u8; 4096];
                loop {
                    tokio::select! {
                        biased;
                        _ = &mut closed => {
                            #[allow(deprecated)]
                            let _ = stream.set_linger(Some(Duration::ZERO));
                            return response;
                        }
                        read = stream.read(&mut chunk) => match read {
                            Ok(0) | Err(_) => return response,
                            Ok(read) => {
                                response.extend_from_slice(&chunk[..read]);
                                let reached = announce.as_ref().is_some_and(|(wanted, _)| {
                                    delivered_sse_frames(&response) >= *wanted
                                });
                                if reached {
                                    if let Some((_, tx)) = announce.take() {
                                        let _ = tx.send(());
                                    }
                                }
                            }
                        },
                    }
                }
            }));
            let (stream, _) =
                match tokio::time::timeout(Duration::from_secs(2), listener.accept()).await {
                    Ok(Ok(accepted)) => accepted,
                    Ok(Err(error)) => {
                        client.abort_and_wait().await;
                        panic!("accept downstream request: {error}");
                    }
                    Err(error) => {
                        client.abort_and_wait().await;
                        panic!("accept downstream request timed out: {error:?}");
                    }
                };
            let mut session = Session::new_h1(Box::new(Stream::from(stream)));
            match tokio::time::timeout(
                Duration::from_secs(2),
                session.as_downstream_mut().read_request(),
            )
            .await
            {
                Ok(Ok(_)) => {}
                Ok(Err(error)) => {
                    client.abort_and_wait().await;
                    panic!("parse downstream request: {error}");
                }
                Err(error) => {
                    client.abort_and_wait().await;
                    panic!("parse downstream request timed out: {error:?}");
                }
            }
            (session, close, client, delivered)
        }

        fn stream_probe_config(upstream_url: &str) -> sbproxy_ai::AiHandlerConfig {
            sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
                "providers": [{
                    "name": "openai",
                    "provider_type": "openai",
                    "base_url": upstream_url,
                    "allow_private_base_url": true,
                    "api_key": "fixture-key"
                }],
                // Pinned rather than left on `auto`, which resolves a
                // loopback host to the generic parser: the test is about
                // what the finalizer does with a snapshot, not about
                // which parser produced it.
                "usage_parser": "openai"
            }))
            .expect("single-provider streaming fixture config")
        }

        /// The same fixture origin with a token cap that blocks.
        ///
        /// `origin` scope so the key is this test's hostname and nothing
        /// else, and `total` so the cap is cumulative rather than
        /// windowed: the process-wide tracker is shared, and a windowed
        /// key would make the assertion depend on which second the test
        /// ran in.
        fn stream_capped_config(
            upstream_url: &str,
            max_tokens: u64,
        ) -> sbproxy_ai::AiHandlerConfig {
            sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
                "providers": [{
                    "name": "openai",
                    "provider_type": "openai",
                    "base_url": upstream_url,
                    "allow_private_base_url": true,
                    "api_key": "fixture-key"
                }],
                "usage_parser": "openai",
                "budget": {
                    "limits": [{
                        "scope": "origin",
                        "max_tokens": max_tokens,
                        "period": "total"
                    }],
                    "on_exceed": "block"
                }
            }))
            .expect("capped streaming fixture config")
        }

        /// The fixture origin under a provider name of its own, so a
        /// per-provider metric series belongs to one test and the
        /// process-wide registry cannot make the assertion depend on
        /// what else ran.
        fn stream_probe_config_named(
            upstream_url: &str,
            provider: &str,
        ) -> sbproxy_ai::AiHandlerConfig {
            sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
                "providers": [{
                    "name": provider,
                    "provider_type": "openai",
                    "base_url": upstream_url,
                    "allow_private_base_url": true,
                    "api_key": "fixture-key"
                }],
                "usage_parser": "openai"
            }))
            .expect("named streaming fixture config")
        }

        /// Value of `sbproxy_ai_usage_parse_miss_total` for one label
        /// triple.
        fn parse_miss_total(provider: &str, usage_source: &str) -> u64 {
            prometheus::gather()
                .iter()
                .filter(|family| family.name() == "sbproxy_ai_usage_parse_miss_total")
                .flat_map(|family| family.get_metric())
                .find(|metric| {
                    let labels = metric.get_label();
                    labels
                        .iter()
                        .any(|label| label.name() == "provider" && label.value() == provider)
                        && labels.iter().any(|label| {
                            label.name() == "usage_source" && label.value() == usage_source
                        })
                })
                .map(|metric| metric.get_counter().value() as u64)
                .unwrap_or(0)
        }

        /// Seam: the counter that says a 2xx stream was billed nothing.
        ///
        /// The `absent` branch used to return before
        /// `record_ai_usage_parse_miss`, so the one outcome an operator
        /// most needs to see - a delivered response that moved no cap -
        /// left no counter, and the only trace of it was a `debug!` that
        /// `release_max_level_info` strips from the shipped binary. A
        /// flat zero on the counter read as "the fallback is not being
        /// used" when it meant "nothing is being billed".
        #[tokio::test]
        async fn a_stream_that_bills_nothing_ticks_the_absent_label() {
            let provider = "absent-label-probe";
            let before = parse_miss_total(provider, "absent");

            // A stream with no usage frame and no assistant text: the
            // estimator has nothing to count, so the settlement takes
            // the `absent` branch.
            let (url, upstream) = streaming_upstream_fixture(vec![sse("[DONE]")], 1, 0).await;
            let config = stream_probe_config_named(&url, provider);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) =
                streaming_downstream_session(stream_probe_request()).await;
            let mut context = crate::context::RequestContext::new();
            tokio::time::timeout(
                Duration::from_secs(10),
                super::super::handle_ai_proxy(
                    &mut session,
                    &config,
                    &pipeline,
                    "absent-label-probe.test",
                    &mut context,
                    None,
                ),
            )
            .await
            .expect("the stream is answered")
            .expect("the relay serves the stream");
            drop(session);
            let _ = live_downstream_body(client).await;
            drop(close);
            upstream.outcome.abort();

            assert_eq!(
                context.ai_usage_source,
                Some("absent"),
                "the fixture has to reach the branch that bills nothing"
            );
            assert_eq!(
                parse_miss_total(provider, "absent"),
                before + 1,
                "a 2xx stream billed nothing left no counter behind"
            );
        }

        fn stream_probe_request() -> serde_json::Value {
            serde_json::json!({
                "model": "gpt-4o-mini",
                "stream": true,
                "messages": [{"role": "user", "content": "fixture prompt for the stream"}]
            })
        }

        /// Seam: an unwinding panic inside the frame loop.
        ///
        /// The relay's frame loop runs guardrail classifiers, format
        /// translators and PII restorers over caller- and
        /// provider-controlled bytes. A panic in any of them unwinds
        /// through `relay_ai_stream`, which is one of the two exits a
        /// settlement written as a statement after the loop's `.await`
        /// cannot cover; the provider had already been paid and every
        /// reservation refunded. `Drop` covers it by the language's own
        /// guarantee, so this drives the guard directly and unwinds
        /// through it.
        #[test]
        fn a_panic_in_the_relay_still_settles_through_the_guard() {
            use crate::server::ai_dispatch::{
                RouterTokenSink, StreamAccounting, StreamSettleGuard, StreamUsageParserArgs,
            };

            let router = sbproxy_ai::Router::new(sbproxy_ai::RoutingStrategy::FallbackChain, 1);
            let providers: Vec<sbproxy_ai::ProviderConfig> = Vec::new();
            let sink = RouterTokenSink {
                router: &router,
                config_providers: &providers,
                provider_name: "openai",
            };
            let parser_args = StreamUsageParserArgs {
                configured: "openai".to_string(),
                upstream_host: None,
                content_type: None,
                x_provider: None,
            };
            let mut context = crate::context::RequestContext::new();
            context.ai_prompt_tokens_est = Some(9);

            let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let mut ctx = Some(&mut context);
                let mut acct = StreamAccounting::new(200, &parser_args);
                if let Some(estimator) = acct.output_estimator.as_mut() {
                    estimator.feed(
                        br#"data: {"choices":[{"delta":{"content":"the quick brown fox jumps over the lazy dog"}}]}
"#,
                    );
                }
                let _guard = StreamSettleGuard::new(
                    acct,
                    &mut ctx,
                    None,
                    &sink,
                    tracing::Span::none(),
                    "gpt-4o-mini".to_string(),
                );
                panic!("a frame handler panicked mid-stream");
            }));

            assert!(unwound.is_err(), "the fixture has to actually unwind");
            assert_eq!(
                context.ai_usage_source,
                Some("estimated"),
                "an unwinding stream has to settle what it delivered"
            );
            assert!(
                context.ai_tokens_out.unwrap_or(0) > 0,
                "the tokens the provider generated before the panic were not settled"
            );
        }

        /// Seam: the relay's downstream write, and the settlement that
        /// used to sit behind it.
        ///
        /// A client that hangs up mid-stream fails the relay's next
        /// write. Every one of those writes propagates with `?`, and the
        /// settlement was after the loop, so the exact usage the
        /// provider had already sent was parsed and then dropped on the
        /// floor: no context stamp, no budget debit, a reservation
        /// refunded in full, and a receipt that priced the call as
        /// delivered because a pingora write error carries no error
        /// source.
        #[tokio::test]
        async fn a_client_that_hangs_up_mid_stream_still_settles_what_it_received() {
            let frames = vec![
                content_frame("hello"),
                usage_frame(11, 7),
                content_frame("more"),
            ];
            let (upstream_url, upstream) = streaming_upstream_fixture(frames, 2, 3000).await;
            let config = stream_probe_config(&upstream_url);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) =
                streaming_downstream_session(stream_probe_request()).await;
            let mut context = crate::context::RequestContext::new();

            let StreamUpstream { announced, outcome } = upstream;
            let dispatch = super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            );
            let walk_away = async {
                let _ = announced.await;
                // The usage frame is on the wire. Whatever the relay
                // writes next is written into a broken connection.
                tokio::time::sleep(Duration::from_millis(20)).await;
                let _ = close.send(());
            };
            let (result, ()) = tokio::join!(dispatch, walk_away);

            let error = result.expect_err("a stream whose client is gone cannot succeed");
            assert_eq!(
                *error.esource(),
                pingora_error::ErrorSource::Downstream,
                "a failed relay write is the client's failure, not the provider's: {error}"
            );
            assert!(
                crate::server::proxy_http::client_disconnected(
                    Some(error.esource().clone()),
                    crate::server::proxy_http::downstream_half_closed(&session),
                ),
                "the abandoned stream must settle as client_disconnected, not as a delivered sale"
            );
            assert_eq!(
                context.ai_tokens_in,
                Some(11),
                "the usage frame arrived before the disconnect, so its prompt count must survive"
            );
            assert_eq!(
                context.ai_tokens_out,
                Some(7),
                "the usage frame arrived before the disconnect, so its output count must survive"
            );
            let observed = tokio::time::timeout(Duration::from_secs(10), outcome)
                .await
                .expect("the provider connection settles once the client is gone")
                .expect("streaming upstream fixture");
            assert_eq!(
                observed,
                StreamUpstreamOutcome::Abandoned,
                "the upstream body must be dropped, not left draining"
            );
            drop(session);
            drop(client);
        }

        /// Seam: the context fields every usage consumer reads.
        ///
        /// A clean stream with an exact usage frame debited the budget
        /// and never wrote `ai_tokens_in` / `ai_tokens_out`, so the
        /// access log, the usage sinks and the payment bridge all
        /// reported zero tokens for a request the provider had counted
        /// precisely.
        #[tokio::test]
        async fn a_clean_stream_stamps_the_usage_its_consumers_read() {
            let frames = vec![
                content_frame("hello"),
                content_frame(" world"),
                usage_frame(23, 5),
                sse("[DONE]"),
            ];
            let (upstream_url, upstream) = streaming_upstream_fixture(frames, 4, 0).await;
            let config = stream_probe_config(&upstream_url);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) =
                streaming_downstream_session(stream_probe_request()).await;
            let mut context = crate::context::RequestContext::new();

            let result = tokio::time::timeout(
                Duration::from_secs(10),
                super::super::handle_ai_proxy(
                    &mut session,
                    &config,
                    &pipeline,
                    "ai.test",
                    &mut context,
                    None,
                ),
            )
            .await
            .expect("the stream completes");
            result.expect("a clean stream is served");

            assert_eq!(
                context.ai_tokens_in,
                Some(23),
                "the provider's prompt count has to reach the request context"
            );
            assert_eq!(
                context.ai_tokens_out,
                Some(5),
                "the provider's output count has to reach the request context"
            );
            let _ = close.send(());
            let _ = tokio::time::timeout(Duration::from_secs(5), upstream.outcome).await;
            drop(session);
            drop(client);
        }

        /// Seam: a 2xx stream that carried no usage frame at all.
        ///
        /// OpenAI and Azure omit usage from a stream unless the caller
        /// asks for `stream_options.include_usage`, and this gateway
        /// does not ask. Without a fallback the parser snapshot is
        /// `None`, nothing is recorded, and the ticket's headline
        /// scenario follows: ordinary `stream: true` calls succeed
        /// forever against a token cap that never moves.
        ///
        /// The cap is the assertion because it is the consequence. A
        /// second identical stream has to be refused, which it can only
        /// be if the first one debited something.
        #[tokio::test]
        async fn repeated_usage_less_streams_still_trip_the_token_cap() {
            const CAP: u64 = 20;
            let frames = || {
                vec![
                    content_frame("the quick brown fox jumps over the lazy dog"),
                    content_frame(" and then keeps going for a good while longer"),
                    sse("[DONE]"),
                ]
            };
            // The origin scope key is this hostname, so the shared
            // process-wide tracker cannot be moved by another test.
            let hostname = "usage-less-stream-cap.test";
            let pipeline = crate::pipeline::CompiledPipeline::default();

            let (first_url, first_upstream) = streaming_upstream_fixture(frames(), 3, 0).await;
            let config = stream_capped_config(&first_url, CAP);
            let (mut session, close, client) =
                streaming_downstream_session(stream_probe_request()).await;
            let mut context = crate::context::RequestContext::new();
            tokio::time::timeout(
                Duration::from_secs(10),
                super::super::handle_ai_proxy(
                    &mut session,
                    &config,
                    &pipeline,
                    hostname,
                    &mut context,
                    None,
                ),
            )
            .await
            .expect("the first stream completes")
            .expect("the first stream is served");
            let _ = close.send(());
            let _ = tokio::time::timeout(Duration::from_secs(5), first_upstream.outcome).await;
            drop(session);
            drop(client);

            let (second_url, second_upstream) = streaming_upstream_fixture(frames(), 3, 0).await;
            let config = stream_capped_config(&second_url, CAP);
            let (mut session, close, client) =
                streaming_downstream_session(stream_probe_request()).await;
            let mut context = crate::context::RequestContext::new();
            tokio::time::timeout(
                Duration::from_secs(10),
                super::super::handle_ai_proxy(
                    &mut session,
                    &config,
                    &pipeline,
                    hostname,
                    &mut context,
                    None,
                ),
            )
            .await
            .expect("the second request is answered")
            .expect("a budget refusal is a served response, not a relay error");
            // Close the gateway side rather than the client side: the
            // client fixture returns whatever it has buffered the moment
            // it is told to break the connection, which can be nothing.
            // Dropping the session ends the client's read with `Ok(0)`
            // after the refusal has been written.
            drop(session);
            let answer = live_downstream_body(client).await;
            drop(close);
            let answer = String::from_utf8_lossy(&answer);
            assert!(
                answer.starts_with("HTTP/1.1 402"),
                "the first usage-less stream has to spend the cap, so the second is refused: \
                 {answer}"
            );
            // The refusal happens before dispatch, so the second
            // fixture is never called.
            second_upstream.outcome.abort();
        }

        /// The classifier the disconnect attribution rests on, held to
        /// account directly.
        ///
        /// It reads one thing, the pingora `ErrorType`, so what it can
        /// and cannot see is worth pinning: the four types a `Session`
        /// write produces are the client leaving, and the two the relay
        /// raises itself are not. Invert either half and this fails.
        #[test]
        fn only_a_session_write_failure_reads_as_the_client_leaving() {
            use pingora_error::{Error, ErrorType};

            for etype in [
                ErrorType::WriteError,
                ErrorType::WriteTimedout,
                ErrorType::ConnectionClosed,
                ErrorType::H2Error,
            ] {
                let error = Error::explain(etype.clone(), "fixture");
                assert!(
                    super::super::stream_write_failed_downstream(&error),
                    "{etype:?} comes out of a downstream write and nothing else in this relay"
                );
            }
            for etype in [
                ErrorType::HTTPStatus(503),
                ErrorType::InternalError,
                ErrorType::ReadError,
                ErrorType::ConnectTimedout,
            ] {
                let error = Error::explain(etype.clone(), "fixture");
                assert!(
                    !super::super::stream_write_failed_downstream(&error),
                    "{etype:?} is the relay's own failure or the upstream's, not the client's"
                );
            }
        }

        /// What the AI dispatch path actually costs in stack, held to a
        /// budget that can only fall.
        ///
        /// # Why the old guards could not do this
        ///
        /// Every stack guard in this tree measured `size_of` on one
        /// future. A future's size is the state it holds *between*
        /// polls. The stack is the whole chain of frames live *during* a
        /// poll, and one says almost nothing about the other. The
        /// numbers those guards reported, on a tree whose CI lane was
        /// aborting with a stack overflow, were `request_filter` at
        /// 36,480 bytes of a 262,144 budget and `handle_ai_proxy` at
        /// 24,464 of 32,656. Around 96% of what fills the stack was
        /// invisible to them, which is why both stayed green through
        /// three overflows.
        ///
        /// # What this measures instead
        ///
        /// The request runs on a real Pingora runtime worker whose stack
        /// is [`pingora_runtime::DEFAULT_THREAD_STACK_SIZE`], the size
        /// production gives a worker. Pingora's runtime records where
        /// each worker's stack starts, the request path takes the
        /// address of a local at its deepest point, and the difference
        /// is bytes actually in use. Three things are checked, and the
        /// two numbers involved are different tiers:
        ///
        /// 1. The measured depth is inside [`STACK_BUDGET`], which is a
        ///    fraction of that stack and the thing that only falls.
        ///    This is an assertion and not an overflow on purpose: an
        ///    overflow aborts, and an abort has no number and no
        ///    message, which is the wrong failure for the check that
        ///    exists to explain this class of bug. Sizing the worker to
        ///    the budget instead would make this assertion unreachable,
        ///    and would also abort on a path production serves fine.
        /// 2. The request completes at all. A path that outgrows the
        ///    production stack overflows and aborts, which under
        ///    nextest is this test and nothing else, and that covers the
        ///    entire call chain including every frame below the probes:
        ///    reqwest, hyper, the TLS stack, serde.
        /// 3. The probe reported a non-zero depth. Without this the
        ///    measurement could quietly stop working, the budget check
        ///    would pass vacuously, and we would be back to a guard that
        ///    cannot fail.
        ///
        /// # What it still cannot see
        ///
        /// The reported number is the depth at the probes, not the
        /// deepest point reached, so read it as a floor and a trend. The
        /// budget in (1) is the part that covers everything.
        ///
        /// The fixture provider is local plaintext, so no TLS frames sit
        /// on this stack, and no guardrail, translator or holdback
        /// session is wired. Production is deeper than this. The budget
        /// leaves room for that; it is not the whole margin.
        ///
        /// # When this fails
        ///
        /// Do not raise the budget first. Frames added anywhere in the
        /// workspace spend it, so the growth is usually not in the file
        /// that broke this. Boxing is not the answer either: two
        /// extractions on this path moved 528 bytes, 0.025% of a 2 MiB
        /// stack, and cost an afternoon. Raising the worker stack with
        /// `runtime_thread_stack_size` and then raising this budget is a
        /// deliberate decision with an operator-visible cost, and it
        /// belongs in a commit that says so.
        #[test]
        fn the_ai_dispatch_path_stays_inside_its_stack_budget() {
            // The worker gets the *production* stack, not the budget.
            //
            // Sizing it to the budget makes the assertion below dead
            // code: the thread's stack would be the budget, so `used`
            // could not exceed it without the process having already
            // aborted. The first version of this did exactly that while
            // its doc claimed the opposite, which is the third guard
            // over this property in two days that could not fail.
            //
            // Two distinct numbers, and they are not the same tier:
            //
            //   the stack   what production gives a worker, 8 MiB. An
            //               overflow here is a real overflow and aborts,
            //               which is the honest answer to a path that
            //               outgrows what production serves it on.
            //   the budget  what the request path is allowed to use of
            //               that, and the thing that only falls. Passing
            //               it is an assertion failure with the
            //               measurement in hand, long before the cliff.
            let runtime = pingora_runtime::RuntimeBuilder::new(1, "stack-budget")
                .thread_stack_size(pingora_runtime::DEFAULT_THREAD_STACK_SIZE)
                .build();
            // Await the task from here rather than blocking on a
            // channel, so a panic inside it surfaces as a panic instead
            // of as a timeout.
            let task = runtime
                .get_handle()
                .spawn(async { a_streamed_dispatch().await });
            let waiter = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .expect("current-thread runtime to await the worker");
            let used = waiter
                .block_on(task)
                .expect("the request completes on a production-sized worker stack");

            // Printed on every run, not only on failure, and in one
            // grep-able line: the number is the point. CI reads it out
            // of a log and a reviewer comparing two branches wants it
            // without editing the test.
            let budget = super::super::STACK_BUDGET;
            let stack = pingora_runtime::DEFAULT_THREAD_STACK_SIZE;
            println!(
                "STACK_HIGH_WATER_BYTES={used} BUDGET_BYTES={budget} WORKER_STACK_BYTES={stack}"
            );
            assert!(
                used > 0,
                "the stack probe reported nothing. Either the worker stopped recording its \
                 stack base or the probes stopped being reached, and either way this check \
                 has been passing vacuously."
            );
            assert!(
                used <= budget,
                "the AI request path measured {used} bytes against a {budget}-byte budget"
            );
        }

        /// A whole streamed dispatch: header write, chunk loop,
        /// close-out and settlement. Returns the deepest stack usage the
        /// probes saw on this thread.
        ///
        /// Entered through `request_phase::request_filter`, not through
        /// `handle_ai_proxy` directly, and that is the whole point.
        /// `request_filter` is the function every request enters and it
        /// stays live on the stack while everything it dispatches into
        /// runs above it, so a frame added there costs the AI path
        /// exactly as much as one added in the relay. The commit that
        /// broke `main` (`edf8b937`, PR #1235) grew `request_filter`,
        /// `proxy_http`, `context`, `trust_tier` and `hmac_auth` and
        /// touched no AI file at all. A measurement that started at
        /// `handle_ai_proxy` would not have seen a byte of it.
        async fn a_streamed_dispatch() -> usize {
            let frames = vec![content_frame("hello"), usage_frame(11, 7), sse("[DONE]")];
            let (upstream_url, upstream) = streaming_upstream_fixture(frames, 3, 0).await;
            let (mut session, close, client) =
                streaming_downstream_session(stream_probe_request()).await;
            let mut context = super::super::ai_request_context(&upstream_url);

            let served = crate::server::request_phase::request_filter(&mut session, &mut context)
                .await
                .expect("the streamed request completes on a budget-sized worker stack");
            assert!(
                served,
                "request_filter has to serve the AI request itself, not hand it to an upstream \
                 peer: a request that leaves early never reaches the frames this measures"
            );
            assert_eq!(
                context.ai_tokens_out,
                Some(7),
                "the settlement has to run on that stack too, not just the loop"
            );
            let _ = close.send(());
            let _ = upstream.outcome.await;
            drop(session);
            drop(client);
            crate::server::stack_probe::thread_high_water_bytes()
        }

        /// Seam: the buffered relay's terminal write.
        ///
        /// A non-streaming AI response is written in one frame after the
        /// provider has finished, so a caller that hangs up during that
        /// write has already been paid for. Pingora reports the failure
        /// as `WriteError` with no source, so the receipt read
        /// `delivered` when the 2xx header had committed and
        /// `origin_5xx` when it had not: a full sale invoiced for a
        /// response nobody received, and a provider blamed for a
        /// caller's departure.
        ///
        /// The body has to be larger than the socket buffer, or the
        /// kernel absorbs the whole write and the failure never
        /// surfaces.
        #[tokio::test]
        async fn a_client_that_hangs_up_before_the_buffered_write_is_not_a_delivered_sale() {
            let (upstream_url, upstream) = large_buffered_upstream_fixture(4 * 1024 * 1024).await;
            let config = stream_probe_config(&upstream_url);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) = streaming_downstream_session(serde_json::json!({
                "model": "gpt-4o-mini",
                "messages": [{"role": "user", "content": "fixture prompt"}]
            }))
            .await;
            let mut context = crate::context::RequestContext::new();

            let dispatch = super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            );
            let walk_away = async {
                // The provider has the request; break the connection
                // before the gateway finishes writing the answer out.
                tokio::time::sleep(Duration::from_millis(50)).await;
                let _ = close.send(());
            };
            let (result, ()) = tokio::join!(dispatch, walk_away);

            let error = result.expect_err("a client that is gone cannot be served");
            assert_eq!(
                *error.esource(),
                pingora_error::ErrorSource::Downstream,
                "a failed buffered write is the client's failure, not the provider's: {error}"
            );
            assert!(
                crate::server::proxy_http::client_disconnected(
                    Some(error.esource().clone()),
                    crate::server::proxy_http::downstream_half_closed(&session),
                ),
                "the abandoned response must settle as client_disconnected, not as a sale"
            );
            assert!(
                context.ai_upstream_cancelled_on_client_disconnect,
                "the marker is what declines the on_error fallback, which would be a \
                 second paid provider call for a caller who has left"
            );
            upstream.abort();
            drop(session);
            drop(client);
        }

        /// A provider that answers one non-streaming request with a body
        /// of `bytes` bytes.
        ///
        /// Sized past the downstream socket buffer on purpose: a small
        /// body is absorbed by the kernel whatever the peer does, and a
        /// write that never reaches the wire cannot fail.
        async fn large_buffered_upstream_fixture(
            bytes: usize,
        ) -> (String, tokio::task::JoinHandle<()>) {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
                .await
                .expect("bind buffered upstream fixture");
            let address = listener.local_addr().expect("buffered upstream address");
            let handle = tokio::spawn(async move {
                let Ok((mut stream, _)) = listener.accept().await else {
                    return;
                };
                drain_upstream_request(&mut stream).await;
                let filler = "x".repeat(bytes);
                let body = serde_json::json!({
                    "id": "fixture",
                    "choices": [{"message": {"role": "assistant", "content": filler}}],
                    "usage": {"prompt_tokens": 11, "completion_tokens": 7}
                })
                .to_string();
                let header = format!(
                    "HTTP/1.1 200 Fixture\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                    body.len()
                );
                let _ = stream.write_all(header.as_bytes()).await;
                let _ = stream.write_all(body.as_bytes()).await;
                let _ = stream.flush().await;
            });
            (format!("http://{address}/v1"), handle)
        }

        /// A provider that answers one non-streaming chat request with
        /// `body`, verbatim.
        async fn buffered_upstream_fixture(
            body: serde_json::Value,
        ) -> (String, tokio::task::JoinHandle<()>) {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
                .await
                .expect("bind buffered upstream fixture");
            let address = listener.local_addr().expect("buffered upstream address");
            let handle = tokio::spawn(async move {
                let Ok((mut stream, _)) = listener.accept().await else {
                    return;
                };
                drain_upstream_request(&mut stream).await;
                let body = body.to_string();
                let header = format!(
                    "HTTP/1.1 200 Fixture\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                    body.len()
                );
                let _ = stream.write_all(header.as_bytes()).await;
                let _ = stream.write_all(body.as_bytes()).await;
                let _ = stream.flush().await;
            });
            (format!("http://{address}/v1"), handle)
        }

        /// Drive one buffered chat request against `upstream_body` and
        /// return the marker its settlement left on the context.
        async fn buffered_usage_source(
            upstream_body: serde_json::Value,
            hostname: &str,
        ) -> Option<&'static str> {
            let (url, upstream) = buffered_upstream_fixture(upstream_body).await;
            // A budget block, because the buffered relay stamps its
            // token counts (and now the marker that describes them) from
            // inside the budget recorder. A cap far above anything the
            // fixture can spend, so this is the recorder's presence and
            // not its enforcement.
            let config = stream_capped_config(&url, 1_000_000);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) = streaming_downstream_session(serde_json::json!({
                "model": "gpt-4o-mini",
                "messages": [{"role": "user", "content": "fixture prompt for the buffered relay"}]
            }))
            .await;
            let mut context = crate::context::RequestContext::new();
            tokio::time::timeout(
                Duration::from_secs(10),
                super::super::handle_ai_proxy(
                    &mut session,
                    &config,
                    &pipeline,
                    hostname,
                    &mut context,
                    None,
                ),
            )
            .await
            .expect("the buffered request is answered")
            .expect("the buffered relay serves the response");
            drop(session);
            let _ = live_downstream_body(client).await;
            drop(close);
            upstream.abort();
            context.ai_usage_source
        }

        /// Seam: the buffered relay's provenance marker.
        ///
        /// `usage_source` is the field an operator filters the access log
        /// on to find the rows an invoice can be built from, and the one
        /// they drill to from `sbproxy_ai_usage_parse_miss_total`. Only
        /// the streaming settlement wrote it, so every non-streaming AI
        /// row was unmarked: a filter on `measured` dropped all of them,
        /// and a buffered response billed from the same tokenizer
        /// estimate ticked the counter with nothing to drill to.
        ///
        /// Two cases, not three: `absent` needs both no measured usage
        /// and a zero prompt estimate, and a chat request that reached a
        /// provider always has a prompt to estimate, so on this relay
        /// the third value is reachable only from a surface that debits
        /// no estimate at all. The streamed twin covers it in
        /// `a_stream_that_bills_nothing_ticks_the_absent_label`.
        #[tokio::test]
        async fn a_buffered_response_marks_where_its_usage_came_from() {
            let measured = buffered_usage_source(
                serde_json::json!({
                    "id": "fixture",
                    "choices": [{"message": {"role": "assistant", "content": "hello there"}}],
                    "usage": {"prompt_tokens": 11, "completion_tokens": 7}
                }),
                "buffered-measured.test",
            )
            .await;
            assert_eq!(measured, Some("measured"));

            let estimated = buffered_usage_source(serde_json::json!({
                "id": "fixture",
                "choices": [{"message": {"role": "assistant", "content": "the quick brown fox jumps over the lazy dog"}}]
            }),
            "buffered-estimated.test")
            .await;
            assert_eq!(
                estimated,
                Some("estimated"),
                "a buffered response billed from an estimate has to say so"
            );
        }

        /// The whole `handle_ai_proxy` state machine sits on a pingora
        /// worker's stack while it is polled, 8 MiB since WOR-2699, and
        /// it is not alone there: the compression pipeline, the CEL policy plane and the
        /// provider client each add their own frames on top of it.
        ///
        /// WOR-2622: this path had roughly a kilobyte of headroom and
        /// nothing measured it. Adding the settle guard pushed the
        /// future from 26,080 bytes to 27,568, and the debug-profile
        /// proxy then died with
        /// `thread 'Pingora HTTP Proxy Service' has overflowed its
        /// stack` on the one e2e origin that runs compression and an
        /// `ai_policy` expression together
        /// (`e2e/tests/governed_key_policy.rs`'s
        /// `compression-cel.localhost`). Boxing the two relay futures
        /// took it to 24,464.
        ///
        /// This is a size, not a depth, and the difference is the whole
        /// lesson of WOR-2699.
        /// `the_ai_dispatch_path_stays_inside_its_stack_budget` measures
        /// the stack the dispatch actually uses, which is the number a
        /// worker's budget is spent on and the one that overflows. This
        /// measures the state the future holds between polls: a much
        /// smaller number, worth its own line because it is also the
        /// per-in-flight-request memory cost, and because it fails on
        /// growth rather than at a cliff. Neither substitutes for the
        /// other, and this one alone says nothing about an overflow: on
        /// a tree whose smoke lane was aborting, guards of this shape
        /// reported 14% and 75% of their budgets and stayed green.
        ///
        /// The budget is deliberately below where the failure was
        /// observed rather than at it.
        #[tokio::test]
        async fn the_dispatch_future_stays_inside_its_stack_budget() {
            const BUDGET_BYTES: usize = 25 * 1024;

            let (url, upstream) = streaming_upstream_fixture(vec![sse("[DONE]")], 1, 0).await;
            let config = stream_probe_config(&url);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) =
                streaming_downstream_session(stream_probe_request()).await;
            let mut context = crate::context::RequestContext::new();

            // Built and never polled: the size is a property of the type.
            let dispatch = super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            );
            let size = std::mem::size_of_val(&dispatch);
            drop(dispatch);

            drop(session);
            drop(close);
            drop(client);
            upstream.outcome.abort();

            assert!(
                size <= BUDGET_BYTES,
                "the AI dispatch future is {size} bytes, over its {BUDGET_BYTES}-byte budget. \
                 It is polled on an 8 MiB pingora worker stack under the compression pipeline \
                 and the policy plane; box the deepest new future rather than raising this."
            );
        }

        /// Seam: the request future being dropped mid-stream.
        ///
        /// A graceful shutdown that abandons in-flight streaming tasks,
        /// or any task-level timeout wrapped around the dispatch, drops
        /// the future while the relay is still forwarding chunks. With
        /// the settlement as a statement after the frame loop's `.await`
        /// that drop settled nothing: every reservation refunded, no cap
        /// moved, and the provider had already been paid for the tokens
        /// it generated. The settlement is a `Drop` guard for this
        /// reason, and this is the exit that proves it, since a panic
        /// unwinds through the same guard by the language's own
        /// guarantee.
        ///
        /// The drop is taken on the frames the client has read, not on a
        /// clock. "Mid-stream" is a position in the dispatch, and a
        /// deadline cannot name it: the request side builds the model's
        /// BPE table on the first call in a process, a synchronous block
        /// no timer preempts, and under the test lane's parallelism that
        /// block outran a two-second deadline often enough to red the
        /// gate. The dispatch was then dropped before `relay_ai_stream`
        /// had armed any guard, and a test about what the settlement
        /// does reported that there had been no settlement. Counting
        /// relayed frames is the edge that does name the position: the
        /// relay writes them, and only from inside the guard's scope.
        #[tokio::test]
        async fn a_dropped_dispatch_still_settles_what_the_stream_delivered() {
            const CAP: u64 = 20;
            // Comfortably more completion text than `CAP`, and far
            // fewer frames than the fixture will supply, so the drop
            // lands mid-flight with the cap already exceeded.
            const FRAMES_BEFORE_DROP: usize = 32;
            let hostname = "dropped-stream-cap.test";
            let pipeline = crate::pipeline::CompiledPipeline::default();

            // A long stream so the drop lands mid-flight rather than
            // after the relay has already finished on its own.
            let (first_url, first_upstream) = streaming_upstream_fixture(
                vec![content_frame("the quick brown fox jumps over the lazy dog")],
                1,
                3000,
            )
            .await;
            let config = stream_capped_config(&first_url, CAP);
            let (mut session, close, client, delivered) =
                streaming_downstream_session_watching_frames(
                    stream_probe_request(),
                    Some(FRAMES_BEFORE_DROP),
                )
                .await;
            let mut context = crate::context::RequestContext::new();
            // Boxed so the drop below is the future's own drop. A
            // `Pin<&mut _>` from `tokio::pin!` would only end the borrow
            // at the end of the scope, which is after the assertions
            // that need the settlement to have happened.
            let mut dispatch = Box::pin(super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                hostname,
                &mut context,
                None,
            ));
            // The watchdog is not the synchronization; it is the bound
            // on a relay that never delivers, which is a real failure
            // and says so.
            let mut delivered =
                std::pin::pin!(tokio::time::timeout(Duration::from_secs(30), delivered));
            let finished = tokio::select! {
                result = dispatch.as_mut() => Some(result),
                reached = delivered.as_mut() => {
                    reached
                        .expect(
                            "the relay never delivered its first frames downstream, so the \
                             dispatch was never mid-stream and this test could not run",
                        )
                        .expect(
                            "the downstream client task ended before it counted the frames, \
                             so the relay closed the socket or the fixture itself failed",
                        );
                    None
                }
            };
            assert!(
                finished.is_none(),
                "the fixture has to still be streaming when the future is dropped, but the \
                 dispatch returned first: {finished:?}"
            );
            // The drop, and with it the guard's `Drop`.
            drop(dispatch);
            assert_eq!(
                context.ai_usage_source,
                Some("estimated"),
                "the dropped dispatch has to settle from what it received"
            );
            let settled = context.ai_tokens_in.unwrap_or(0) + context.ai_tokens_out.unwrap_or(0);
            assert!(
                settled > CAP,
                "the abandoned stream settled {settled} tokens, which does not spend the \
                 {CAP}-token cap the refusal below depends on"
            );
            let _ = close.send(());
            first_upstream.outcome.abort();
            drop(session);
            drop(client);

            // The cap is the consequence: a second stream on the same
            // origin scope has to be refused, which can only happen if
            // the abandoned one debited.
            let (second_url, second_upstream) =
                streaming_upstream_fixture(vec![content_frame("hello"), sse("[DONE]")], 2, 0).await;
            let config = stream_capped_config(&second_url, CAP);
            let (mut session, close, client) =
                streaming_downstream_session(stream_probe_request()).await;
            let mut context = crate::context::RequestContext::new();
            tokio::time::timeout(
                Duration::from_secs(10),
                super::super::handle_ai_proxy(
                    &mut session,
                    &config,
                    &pipeline,
                    hostname,
                    &mut context,
                    None,
                ),
            )
            .await
            .expect("the second request is answered")
            .expect("a budget refusal is a served response, not a relay error");
            drop(session);
            let answer = live_downstream_body(client).await;
            let answer = String::from_utf8_lossy(&answer);
            assert!(
                answer.starts_with("HTTP/1.1 402"),
                "the abandoned stream has to spend the cap, so the second is refused: {answer}"
            );
            drop(close);
            second_upstream.outcome.abort();
        }
    }
    mod client_disconnect_tests {
        use super::*;

        /// What a slow provider fixture saw happen to its connection.
        #[derive(Debug, PartialEq, Eq)]
        enum SlowUpstreamOutcome {
            /// The gateway closed the connection before the hold
            /// elapsed, which is the generation not being paid for.
            Abandoned,
            /// The hold elapsed with the gateway still waiting, and the
            /// fixture answered.
            Answered,
        }

        struct SlowUpstream {
            /// Fires once the fixture has read a whole request off the wire.
            dispatched: tokio::sync::oneshot::Receiver<()>,
            outcome: tokio::task::JoinHandle<SlowUpstreamOutcome>,
        }

        /// A provider that takes `hold` to answer, and reports whether
        /// the gateway was still there when it did.
        ///
        /// The `upstream_fixture` family replies the instant it has read
        /// the request, which is the wrong shape for a test about what
        /// happens *during* a generation. This one stands in for a real
        /// completion call: it holds the connection open with nothing
        /// written, so the gateway parks on the response header exactly
        /// as it does against a provider composing a long answer, and
        /// the fixture can say afterwards whether that wait was
        /// cancelled or served.
        async fn slow_upstream_fixture(hold: Duration) -> (String, SlowUpstream) {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
                .await
                .expect("bind slow upstream fixture");
            let address = listener.local_addr().expect("slow upstream address");
            let (announce, dispatched) = tokio::sync::oneshot::channel();
            let outcome = tokio::spawn(async move {
                let (mut stream, _) = listener.accept().await.expect("accept upstream request");
                drain_upstream_request(&mut stream).await;
                let _ = announce.send(());
                let mut probe = [0_u8; 1];
                tokio::select! {
                    // `Ok(0)` is the gateway's FIN and an error is its
                    // reset. Either way the call it made was dropped
                    // before this fixture produced a token.
                    _ = stream.read(&mut probe) => SlowUpstreamOutcome::Abandoned,
                    () = tokio::time::sleep(hold) => {
                        let body = br#"{"choices":[{"message":{"content":"late"}}]}"#;
                        let header = format!(
                            "HTTP/1.1 200 Fixture\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                            body.len()
                        );
                        let _ = stream.write_all(header.as_bytes()).await;
                        let _ = stream.write_all(body).await;
                        SlowUpstreamOutcome::Answered
                    }
                }
            });
            (
                format!("http://{address}/v1"),
                SlowUpstream {
                    dispatched,
                    outcome,
                },
            )
        }

        /// How a downstream fixture ends its connection.
        #[derive(Clone, Copy, PartialEq, Eq)]
        enum DownstreamClose {
            /// `SO_LINGER` at zero, then close: the peer's connection is
            /// broken and the gateway's next read fails. This is the
            /// hard signal, and it cancels whatever the origin config
            /// says.
            Reset,
            /// Shut the write half down and go on reading, which is the
            /// RFC 9112 section 9.6 shape. Cancels only where the origin
            /// sets `cancel_on_half_close`.
            HalfClose,
        }

        /// A downstream client that keeps both halves of its connection
        /// open until the test breaks it.
        ///
        /// [`downstream_wire_session`] shuts its write side down the
        /// moment the request is written, which is the polite RFC 9112
        /// section 9.6 shape and one the watch deliberately never acts
        /// on. A test about a caller whose connection is gone needs the
        /// other shape: a connection that is whole when the provider
        /// call starts and reset while it is running.
        async fn downstream_session_closing_on_demand(
            body: serde_json::Value,
            close_as: DownstreamClose,
        ) -> (Session, tokio::sync::oneshot::Sender<()>, DownstreamClient) {
            let body = serde_json::to_vec(&body).expect("request JSON");
            let mut wire = format!(
                "POST /v1/chat/completions HTTP/1.1\r\nHost: ai.test\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                body.len()
            )
            .into_bytes();
            wire.extend_from_slice(&body);

            let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
                .await
                .expect("bind downstream fixture");
            let address = listener.local_addr().expect("downstream address");
            let (close, mut closed) = tokio::sync::oneshot::channel::<()>();
            let mut client = DownstreamClient::new(tokio::spawn(async move {
                let stream = tokio::net::TcpStream::connect(address)
                    .await
                    .expect("connect downstream fixture");
                let mut stream = stream;
                stream.write_all(&wire).await.expect("write request");
                // Deliberately no `shutdown()`: both halves stay open,
                // so the gateway sees a live client right up to the
                // moment the test breaks the connection below.
                let mut response = Vec::new();
                let mut chunk = [0_u8; 4096];
                loop {
                    tokio::select! {
                        biased;
                        _ = &mut closed => {
                            match close_as {
                                DownstreamClose::Reset => {
                                    // Zero-timeout linger turns the
                                    // close into an RST rather than a
                                    // FIN, which is what the gateway
                                    // sees once a peer's connection is
                                    // genuinely broken. Deprecated for
                                    // the blocking-on-drop hazard of a
                                    // *non-zero* linger; a zero linger
                                    // resets at once and blocks on
                                    // nothing.
                                    #[allow(deprecated)]
                                    let _ = stream.set_linger(Some(Duration::ZERO));
                                }
                                DownstreamClose::HalfClose => {
                                    // Write side only. The read half
                                    // stays open, which is precisely
                                    // what makes this shape ambiguous:
                                    // a client doing it may still be
                                    // waiting for the response.
                                    let _ = stream.shutdown().await;
                                    // Keep reading, so the socket is not
                                    // dropped and the FIN is the only
                                    // thing the gateway ever sees.
                                    loop {
                                        match stream.read(&mut chunk).await {
                                            Ok(0) | Err(_) => return response,
                                            Ok(read) => {
                                                response.extend_from_slice(&chunk[..read]);
                                            }
                                        }
                                    }
                                }
                            }
                            return response;
                        }
                        read = stream.read(&mut chunk) => match read {
                            Ok(0) | Err(_) => return response,
                            Ok(read) => response.extend_from_slice(&chunk[..read]),
                        },
                    }
                }
            }));
            let (stream, _) =
                match tokio::time::timeout(Duration::from_secs(2), listener.accept()).await {
                    Ok(Ok(accepted)) => accepted,
                    Ok(Err(error)) => {
                        client.abort_and_wait().await;
                        panic!("accept downstream request: {error}");
                    }
                    Err(error) => {
                        client.abort_and_wait().await;
                        panic!("accept downstream request timed out: {error:?}");
                    }
                };
            let mut session = Session::new_h1(Box::new(Stream::from(stream)));
            match tokio::time::timeout(
                Duration::from_secs(2),
                session.as_downstream_mut().read_request(),
            )
            .await
            {
                Ok(Ok(_)) => {}
                Ok(Err(error)) => {
                    client.abort_and_wait().await;
                    panic!("parse downstream request: {error}");
                }
                Err(error) => {
                    client.abort_and_wait().await;
                    panic!("parse downstream request timed out: {error:?}");
                }
            }
            (session, close, client)
        }

        fn disconnect_probe_config(upstream_url: &str) -> sbproxy_ai::AiHandlerConfig {
            disconnect_probe_config_with_opt_in(upstream_url, false)
        }

        fn disconnect_probe_config_with_opt_in(
            upstream_url: &str,
            cancel_on_half_close: bool,
        ) -> sbproxy_ai::AiHandlerConfig {
            sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
                "providers": [{
                    "name": "openai",
                    "provider_type": "openai",
                    "base_url": upstream_url,
                    "allow_private_base_url": true,
                    "api_key": "fixture-key"
                }],
                "cancel_on_half_close": cancel_on_half_close
            }))
            .expect("single-provider disconnect fixture config")
        }

        /// The buffered twin of
        /// `the_ai_dispatch_path_stays_inside_its_stack_budget`.
        ///
        /// Deleting `a_non_streaming_dispatch_fits_a_pingora_worker_stack`
        /// left the non-streaming relay with no stack coverage at all,
        /// and left the probe in `relay_ai_response_with_cache`
        /// unreached by any test, which means it could stop working and
        /// nothing would notice. The two relays are different functions
        /// with different frames; measuring one says nothing about the
        /// other.
        ///
        /// Same shape as the streaming budget test: entered through
        /// `request_phase::request_filter`, run on a worker with a
        /// production-sized stack, measured against the same budget.
        ///
        /// A connected client, deliberately not `downstream_session`,
        /// which half-closes the instant the request is written. That
        /// FIN would settle the disconnect watch on its first poll and
        /// let the `select!` resolve immediately, so every later poll of
        /// the provider future, including the one that decodes the
        /// response header, would run at the bare `.await` outside the
        /// `select!`. The deeper frame is the one this measures, so the
        /// sender is held and never fired.
        #[test]
        fn the_buffered_ai_dispatch_path_stays_inside_its_stack_budget() {
            let runtime = pingora_runtime::RuntimeBuilder::new(1, "stack-budget-buffered")
                .thread_stack_size(pingora_runtime::DEFAULT_THREAD_STACK_SIZE)
                .build();
            let task = runtime.get_handle().spawn(async {
                let (upstream_url, upstream) =
                    slow_upstream_fixture(Duration::from_millis(50)).await;
                let (mut session, _close, client) = downstream_session_closing_on_demand(
                    disconnect_probe_request(),
                    DownstreamClose::Reset,
                )
                .await;
                let mut context = super::super::ai_request_context(&upstream_url);

                let served =
                    crate::server::request_phase::request_filter(&mut session, &mut context)
                        .await
                        .expect("the request completes on a production-sized worker stack");
                assert!(served, "request_filter has to serve the AI request itself");
                assert!(
                    !context.ai_upstream_cancelled_on_client_disconnect,
                    "the budget must measure a served dispatch, not a cancelled one"
                );
                drop(session);
                let response = live_downstream_body(client).await;
                assert!(response.starts_with(b"HTTP/1.1 200"), "{response:?}");
                let _ = upstream.outcome.await;
                crate::server::stack_probe::thread_high_water_bytes()
            });
            let waiter = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .expect("current-thread runtime to await the worker");
            let used = waiter
                .block_on(task)
                .expect("the request completes on a production-sized worker stack");

            let budget = super::super::STACK_BUDGET;
            let stack = pingora_runtime::DEFAULT_THREAD_STACK_SIZE;
            println!(
                "BUFFERED_STACK_HIGH_WATER_BYTES={used} BUDGET_BYTES={budget} \
                 WORKER_STACK_BYTES={stack}"
            );
            assert!(
                used > 0,
                "the stack probe reported nothing on the buffered path. Either the worker \
                 stopped recording its stack base or the probe in \
                 `relay_ai_response_with_cache` stopped being reached, and either way this \
                 check has been passing vacuously."
            );
            assert!(
                used <= budget,
                "the buffered AI request path used {used} bytes of worker stack, past its \
                 {budget}-byte budget"
            );
        }

        fn disconnect_probe_request() -> serde_json::Value {
            serde_json::json!({
                "model": "requested-model",
                "messages": [{"role": "user", "content": "fixture prompt"}]
            })
        }

        /// A provider URL nothing is listening on, so every attempt
        /// fails at connect and the request ends as an origin failure.
        async fn dead_upstream_url() -> String {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
                .await
                .expect("bind dead upstream fixture");
            let address = listener.local_addr().expect("dead upstream address");
            drop(listener);
            format!("http://{address}/v1")
        }

        /// Seam: the provider await inside the live non-streaming
        /// dispatcher.
        ///
        /// Before WOR-2690 nothing watched the client during that await,
        /// so a caller whose connection broke left the generation
        /// running and the invoice arrived seconds after the connection
        /// did not. Without the race this test waits out the fixture's
        /// whole hold and then asserts against a served response, which
        /// is the bug.
        #[tokio::test]
        async fn a_client_whose_connection_breaks_cancels_the_provider_call() {
            let (upstream_url, upstream) = slow_upstream_fixture(Duration::from_secs(8)).await;
            let config = disconnect_probe_config(&upstream_url);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) = downstream_session_closing_on_demand(
                disconnect_probe_request(),
                DownstreamClose::Reset,
            )
            .await;
            let mut context = crate::context::RequestContext::new();

            let SlowUpstream {
                dispatched,
                outcome,
            } = upstream;
            let dispatch = super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            );
            let walk_away = async {
                dispatched.await.expect("the provider received the request");
                let _ = close.send(());
            };
            let (result, ()) = tokio::join!(dispatch, walk_away);

            let error = result.expect_err("a client that is gone cannot be served");
            assert_eq!(
                *error.esource(),
                pingora_error::ErrorSource::Downstream,
                "the failure has to read as the client's, not the provider's: {error}"
            );
            assert!(
                context.ai_upstream_cancelled_on_client_disconnect,
                "the cancellation must be marked on the request, which is what \
                 declines the on_error fallback"
            );
            // The seam WOR-2335 prices the request through. A
            // cancellation that did not classify here would abandon the
            // provider call and still bill it as delivered.
            assert!(
                crate::server::proxy_http::client_disconnected(
                    Some(error.esource().clone()),
                    crate::server::proxy_http::downstream_half_closed(&session),
                ),
                "the cancelled call must settle as client_disconnected"
            );
            let observed = tokio::time::timeout(Duration::from_secs(5), outcome)
                .await
                .expect("the provider connection settles once the client is gone")
                .expect("slow upstream fixture");
            assert_eq!(
                observed,
                SlowUpstreamOutcome::Abandoned,
                "the provider connection must be closed, not left generating"
            );
            drop(session);
            drop(client);
        }

        /// The earliest departures are the ones an earlier revision
        /// billed in full: it settled the connection state before the
        /// attempt loop and treated any answer as "polite half-closer,
        /// stand down", so a caller already gone at dispatch paid for a
        /// whole generation. There is no settle now, so a connection
        /// that is already broken cancels on the first poll.
        #[tokio::test]
        async fn a_connection_already_broken_at_dispatch_cancels_immediately() {
            let (upstream_url, upstream) = slow_upstream_fixture(Duration::from_secs(8)).await;
            let config = disconnect_probe_config(&upstream_url);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) = downstream_session_closing_on_demand(
                disconnect_probe_request(),
                DownstreamClose::Reset,
            )
            .await;
            let mut context = crate::context::RequestContext::new();

            // Break it before dispatch, and give the reset time to land
            // so the test is about the rule rather than about a packet.
            let _ = close.send(());
            tokio::time::sleep(Duration::from_millis(150)).await;

            let started = std::time::Instant::now();
            let error = super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            )
            .await
            .expect_err("a client that is already gone cannot be served");

            assert_eq!(*error.esource(), pingora_error::ErrorSource::Downstream);
            assert!(
                context.ai_upstream_cancelled_on_client_disconnect,
                "an early departure is still a cancellation"
            );
            assert!(
                started.elapsed() < Duration::from_secs(4),
                "the request must not wait out the generation it cancelled: {:?}",
                started.elapsed()
            );
            drop(session);
            drop(client);
            drop(upstream);
        }

        /// A client that is merely slow is a client. Only a broken
        /// connection cancels, which is why the signal is the downstream
        /// connection itself and not a deadline on how long the provider
        /// is taking.
        #[tokio::test]
        async fn a_slow_but_connected_client_is_not_cancelled() {
            let (upstream_url, upstream) = slow_upstream_fixture(Duration::from_millis(400)).await;
            let config = disconnect_probe_config(&upstream_url);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, _close, client) = downstream_session_closing_on_demand(
                disconnect_probe_request(),
                DownstreamClose::Reset,
            )
            .await;
            let mut context = crate::context::RequestContext::new();

            super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            )
            .await
            .expect("a connected client's request is served");
            assert!(!context.ai_upstream_cancelled_on_client_disconnect);
            drop(session);
            let response = live_downstream_body(client).await;

            assert!(response.starts_with(b"HTTP/1.1 200"), "{response:?}");
            let observed = tokio::time::timeout(Duration::from_secs(5), upstream.outcome)
                .await
                .expect("the provider fixture settles")
                .expect("slow upstream fixture");
            assert_eq!(observed, SlowUpstreamOutcome::Answered);
        }

        /// RFC 9112 section 9.6 lets a client shut its write side and go
        /// on reading, and that FIN is byte-for-byte what a departure
        /// looks like. By default it never cancels, so a client that
        /// half-closes on its way in is served exactly as it always was.
        /// The opt-in that changes this answer is exercised below.
        #[tokio::test]
        async fn a_half_close_does_not_cancel_while_the_opt_in_is_off() {
            let (upstream_url, upstream) = slow_upstream_fixture(Duration::from_millis(400)).await;
            let config = disconnect_probe_config(&upstream_url);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            // This fixture half-closes as soon as the request is written.
            let (mut session, client) = downstream_session(disconnect_probe_request()).await;
            let mut context = crate::context::RequestContext::new();

            super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            )
            .await
            .expect("a half-closed client is still owed its response");
            assert!(!context.ai_upstream_cancelled_on_client_disconnect);
            drop(session);
            let response = live_downstream_body(client).await;

            assert!(response.starts_with(b"HTTP/1.1 200"), "{response:?}");
            let observed = tokio::time::timeout(Duration::from_secs(5), upstream.outcome)
                .await
                .expect("the provider fixture settles")
                .expect("slow upstream fixture");
            assert_eq!(observed, SlowUpstreamOutcome::Answered);
        }

        /// The watch must be able to observe a request without changing
        /// how that request is billed.
        ///
        /// Nothing on the AI path had ever read the downstream
        /// connection, so `downstream_half_closed` was always false
        /// there. A watch built on Pingora's `read_body_or_idle` sets
        /// the session's `half_closed` flag on the same read that
        /// observes a FIN, and `client_disconnected`'s
        /// `downstream_half_closed && delivery_failed` arm then fires for
        /// a request that was never cancelled at all: a provider outage
        /// that priced `origin_5xx` (billable `no`) would price
        /// `client_disconnected` (billable `partial`) instead, on a
        /// signed receipt, and the dispute evidence would say the client
        /// left when the provider failed.
        #[tokio::test]
        async fn a_failed_request_from_a_half_closing_client_is_still_an_origin_failure() {
            let config = disconnect_probe_config(&dead_upstream_url().await);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            // Half-closes as soon as the request is written.
            let (mut session, client) = downstream_session(disconnect_probe_request()).await;
            let mut context = crate::context::RequestContext::new();

            let error = super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            )
            .await
            .expect_err("every provider failed to connect");

            assert!(
                !context.ai_upstream_cancelled_on_client_disconnect,
                "nothing was cancelled here"
            );
            // Exactly the two values `logging()` computes and hands the
            // classifier.
            let half_closed = crate::server::proxy_http::downstream_half_closed(&session);
            assert!(
                !half_closed,
                "watching the request must not record a half-close it merely observed"
            );
            assert!(
                !crate::server::proxy_http::client_disconnected(
                    Some(error.esource().clone()),
                    half_closed,
                ),
                "a provider outage must stay an origin failure, not become a \
                 partially billable client_disconnected"
            );
            drop(session);
            drop(client);
        }

        /// The opt-in, at the seam an operator actually configures: one
        /// boolean on the `ai_proxy` action, and the FIN that was
        /// tolerated a test above now cancels the provider call and
        /// bills the request as a client disconnect.
        ///
        /// The half-close arrives while the race is armed, which is the
        /// shape the flag exists for: a caller whose own deadline fired
        /// mid-generation. A FIN already queued when the race arms takes
        /// the same path, because the watch is a real await rather than
        /// a look taken once.
        #[tokio::test]
        async fn a_half_close_cancels_when_the_operator_opts_in() {
            let (upstream_url, upstream) = slow_upstream_fixture(Duration::from_secs(8)).await;
            let config = disconnect_probe_config_with_opt_in(&upstream_url, true);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, close, client) = downstream_session_closing_on_demand(
                disconnect_probe_request(),
                DownstreamClose::HalfClose,
            )
            .await;
            let mut context = crate::context::RequestContext::new();

            let SlowUpstream {
                dispatched,
                outcome,
            } = upstream;
            let dispatch = super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            );
            let walk_away = async {
                dispatched.await.expect("the provider received the request");
                let _ = close.send(());
            };
            let (result, ()) = tokio::join!(dispatch, walk_away);

            let error = result.expect_err("the opt-in reads a half-close as a departure");
            assert_eq!(
                *error.esource(),
                pingora_error::ErrorSource::Downstream,
                "the failure has to read as the client's: {error}"
            );
            assert!(context.ai_upstream_cancelled_on_client_disconnect);
            assert!(
                crate::server::proxy_http::client_disconnected(
                    Some(error.esource().clone()),
                    crate::server::proxy_http::downstream_half_closed(&session),
                ),
                "an opted-in cancellation must settle as client_disconnected"
            );
            let observed = tokio::time::timeout(Duration::from_secs(5), outcome)
                .await
                .expect("the provider connection settles once the client is gone")
                .expect("slow upstream fixture");
            assert_eq!(
                observed,
                SlowUpstreamOutcome::Abandoned,
                "the provider connection must be closed, not left generating"
            );
            drop(session);
            drop(client);
        }

        /// The opt-in must buy the FIN and nothing else. A caller that
        /// keeps its connection whole is still a caller, however long the
        /// provider takes, because there is still no timer anywhere in
        /// this.
        #[tokio::test]
        async fn a_connected_client_is_not_cancelled_under_the_opt_in() {
            let (upstream_url, upstream) = slow_upstream_fixture(Duration::from_millis(400)).await;
            let config = disconnect_probe_config_with_opt_in(&upstream_url, true);
            let pipeline = crate::pipeline::CompiledPipeline::default();
            let (mut session, _close, client) = downstream_session_closing_on_demand(
                disconnect_probe_request(),
                DownstreamClose::Reset,
            )
            .await;
            let mut context = crate::context::RequestContext::new();

            super::super::handle_ai_proxy(
                &mut session,
                &config,
                &pipeline,
                "ai.test",
                &mut context,
                None,
            )
            .await
            .expect("a connected client's request is served with the opt-in on");
            assert!(!context.ai_upstream_cancelled_on_client_disconnect);
            drop(session);
            let response = live_downstream_body(client).await;

            assert!(response.starts_with(b"HTTP/1.1 200"), "{response:?}");
            let observed = tokio::time::timeout(Duration::from_secs(5), upstream.outcome)
                .await
                .expect("the provider fixture settles")
                .expect("slow upstream fixture");
            assert_eq!(observed, SlowUpstreamOutcome::Answered);
        }

        /// The config key itself, because a flag the dispatcher reads
        /// correctly from a struct nobody can populate is not a feature.
        #[test]
        fn the_opt_in_is_off_unless_the_operator_writes_it() {
            let without = sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
                "providers": [{"name": "openai", "api_key": "fixture-key"}]
            }))
            .expect("config without the key");
            assert!(
                !without.cancel_on_half_close,
                "the safe reading is the default"
            );

            let with = sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
                "providers": [{"name": "openai", "api_key": "fixture-key"}],
                "cancel_on_half_close": true
            }))
            .expect("config with the key");
            assert!(
                with.cancel_on_half_close,
                "an operator who writes the key gets it"
            );
        }
    }
    struct QualityVerdictHook {
        scores: Option<Vec<crate::hooks::QualityScore>>,
        minimum_score: f64,
    }

    #[async_trait::async_trait]
    impl crate::hooks::QualityScoringHook for QualityVerdictHook {
        fn minimum_score(&self) -> f64 {
            self.minimum_score
        }

        async fn score_providers(
            &self,
            _req: &crate::hooks::QualityRequest,
        ) -> Option<Vec<crate::hooks::QualityScore>> {
            self.scores.clone()
        }
    }

    fn quality_hook_pipeline(
        scores: Option<Vec<crate::hooks::QualityScore>>,
    ) -> crate::pipeline::CompiledPipeline {
        let mut pipeline = crate::pipeline::CompiledPipeline::default();
        pipeline.hooks.quality_scoring = Some(Arc::new(QualityVerdictHook {
            scores,
            minimum_score: 0.0,
        }));
        pipeline
    }

    fn threshold_quality_hook_pipeline(
        scores: Vec<crate::hooks::QualityScore>,
        minimum_score: f64,
    ) -> crate::pipeline::CompiledPipeline {
        let mut pipeline = crate::pipeline::CompiledPipeline::default();
        pipeline.hooks.quality_scoring = Some(Arc::new(QualityVerdictHook {
            scores: Some(scores),
            minimum_score,
        }));
        pipeline
    }

    fn two_provider_quality_config(
        first_url: &str,
        second_url: &str,
    ) -> sbproxy_ai::AiHandlerConfig {
        sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
            "providers": [
                {
                    "name": "first",
                    "provider_type": "openai",
                    "base_url": first_url,
                    "allow_private_base_url": true,
                    "api_key": "fixture-key"
                },
                {
                    "name": "second",
                    "provider_type": "openai",
                    "base_url": second_url,
                    "allow_private_base_url": true,
                    "api_key": "fixture-key"
                }
            ],
            "routing": {"strategy": "round_robin"}
        }))
        .expect("quality-routing fixture config")
    }

    fn quality_routing_decisions_count(outcome: &str) -> f64 {
        prometheus::gather()
            .into_iter()
            .find(|family| family.name() == "sbproxy_ai_quality_routing_decisions_total")
            .map(|family| {
                family
                    .get_metric()
                    .iter()
                    .filter(|metric| {
                        metric
                            .get_label()
                            .iter()
                            .any(|label| label.name() == "outcome" && label.value() == outcome)
                    })
                    .map(|metric| metric.get_counter().value())
                    .sum()
            })
            .unwrap_or_default()
    }

    fn intent_detection_source_count(source: &str) -> f64 {
        prometheus::gather()
            .into_iter()
            .find(|family| family.name() == "sbproxy_ai_intent_detection_source_total")
            .map(|family| {
                family
                    .get_metric()
                    .iter()
                    .filter(|metric| {
                        metric
                            .get_label()
                            .iter()
                            .any(|label| label.name() == "source" && label.value() == source)
                    })
                    .map(|metric| metric.get_counter().value())
                    .sum()
            })
            .unwrap_or_default()
    }

    /// Seam: the registered `QualityScoringHook` inside the live POST
    /// dispatcher. A unit test of `select_by_quality_async` cannot prove the
    /// selected provider reaches the network.
    #[tokio::test]
    async fn quality_hook_selection_reaches_the_selected_post_upstream() {
        let (first_url, first_hits) =
            upstream_fixture(r#"{"choices":[{"message":{"content":"first"}}]}"#).await;
        let (second_url, second_hits) =
            upstream_fixture(r#"{"choices":[{"message":{"content":"second"}}]}"#).await;
        let config = two_provider_quality_config(&first_url, &second_url);
        let pipeline = quality_hook_pipeline(Some(vec![
            crate::hooks::QualityScore {
                provider: "first".into(),
                score: 0.1,
            },
            crate::hooks::QualityScore {
                provider: "second".into(),
                score: 0.9,
            },
        ]));
        let (mut session, client) = downstream_session(serde_json::json!({
            "model": "requested-model",
            "messages": [{"role": "user", "content": "fixture prompt"}]
        }))
        .await;
        let mut context = crate::context::RequestContext::new();
        let selected_before = quality_routing_decisions_count("selected");

        super::handle_ai_proxy(
            &mut session,
            &config,
            &pipeline,
            "ai.test",
            &mut context,
            None,
        )
        .await
        .expect("quality-selected request is dispatched");
        drop(session);
        let response = live_downstream_body(client).await;

        assert!(response.starts_with(b"HTTP/1.1 200"), "{response:?}");
        assert_eq!(first_hits.load(Ordering::SeqCst), 0);
        assert_eq!(second_hits.load(Ordering::SeqCst), 1);
        assert_eq!(
            context.admin_load_balancer_target.as_deref(),
            Some("second")
        );
        assert_eq!(
            context.ai_route_reason.as_deref(),
            Some("quality_hook: selected second")
        );
        assert!(
            quality_routing_decisions_count("selected") > selected_before,
            "a live hook choice must be visible to operators"
        );
    }

