    /// One `sbproxy_ai_service_tier_decisions_total` disposition. Absent
    /// series read as zero, which is what a disposition nobody has recorded
    /// yet looks like.
    fn service_tier_decisions(disposition: &str) -> f64 {
        prometheus::gather()
            .into_iter()
            .find(|family| family.name() == "sbproxy_ai_service_tier_decisions_total")
            .map(|family| {
                family
                    .get_metric()
                    .iter()
                    .filter(|metric| {
                        metric.get_label().iter().any(|label| {
                            label.name() == "disposition" && label.value() == disposition
                        })
                    })
                    .map(|metric| metric.get_counter().value())
                    .sum()
            })
            .unwrap_or_default()
    }

    /// The other half of the same decision. An entry that declares no tier
    /// must strip the caller's, or the config key would only work as an
    /// upgrade and a caller could still escalate on every untiered entry.
    #[tokio::test]
    async fn a_caller_service_tier_is_stripped_when_the_entry_declares_none() {
        let before = service_tier_decisions("caller_tier_stripped");
        let (upstream_url, hits, captured) = capturing_upstream_fixture(
            r#"{"choices":[{"message":{"role":"assistant","content":"ok"}}]}"#,
        )
        .await;
        let config = sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
            "providers": [{
                "name": "openai-default",
                "provider_type": "openai",
                "base_url": upstream_url,
                "allow_private_base_url": true,
                "api_key": "fixture-key"
            }]
        }))
        .expect("untiered proxy config");

        dispatch_chat_request(
            &config,
            serde_json::json!({
                "model": "fixture-model",
                "service_tier": "priority",
                "messages": [{"role": "user", "content": "fixture prompt"}]
            }),
        )
        .await;

        assert_eq!(hits.load(Ordering::SeqCst), 1);
        let body = captured_upstream_json(captured).await;
        assert!(
            body.get("service_tier").is_none(),
            "an entry with no tier must send no tier field: {body}"
        );
        assert_eq!(
            service_tier_decisions("caller_tier_stripped") - before,
            1.0,
            "stripping a caller's tier must be scrapeable"
        );
    }

    async fn captured_upstream_json(
        captured: tokio::task::JoinHandle<Vec<u8>>,
    ) -> serde_json::Value {
        let upstream_request = captured.await.expect("capturing upstream task");
        let request_text = String::from_utf8(upstream_request).expect("upstream request UTF-8");
        serde_json::from_str(
            request_text
                .split_once("\r\n\r\n")
                .expect("upstream request body")
                .1,
        )
        .expect("upstream JSON body")
    }

    /// WOR-2312: a global alias resolves before provider selection, which
    /// is the capability a per-provider `model_map` cannot express.
    ///
    /// Neither provider enumerates `models:`, so the WOR-1534 eligibility
    /// filter treats both as wildcards and round-robin would pick the
    /// first. Only the alias's provider pin sends this request to the
    /// second one. The body that lands upstream also pins the precedence:
    /// the alias resolves `fast` to `gpt-4o-mini`, then the selected
    /// provider's `model_map` renames that to the dated snapshot.
    #[tokio::test]
    async fn a_pinned_model_alias_selects_the_provider_and_the_upstream_model() {
        let (pinned_url, pinned_hits, captured) = capturing_upstream_fixture(
            r#"{"choices":[{"message":{"role":"assistant","content":"ok"}}]}"#,
        )
        .await;
        let (default_url, default_hits) = upstream_fixture(
            r#"{"choices":[{"message":{"role":"assistant","content":"wrong provider"}}]}"#,
        )
        .await;
        let config = sbproxy_ai::AiHandlerConfig::from_config(serde_json::json!({
            "providers": [
                {
                    "name": "default-first",
                    "provider_type": "openai",
                    "base_url": default_url,
                    "allow_private_base_url": true,
                    "api_key": "fixture-key"
                },
                {
                    "name": "alias-target",
                    "provider_type": "openai",
                    "base_url": pinned_url,
                    "allow_private_base_url": true,
                    "api_key": "fixture-key",
                    "model_map": {"gpt-4o-mini": "gpt-4o-mini-2024-07-18"}
                }
            ],
            "routing": "round_robin",
            "model_aliases": [
                {"alias": "fast", "provider": "alias-target", "model_id": "gpt-4o-mini"}
            ]
        }))
        .expect("alias proxy config");
        let request = serde_json::json!({
            "model": "fast",
            "messages": [{"role": "user", "content": "fixture prompt"}]
        });
        let (mut session, client) = downstream_bytes_session(
            "/v1/chat/completions",
            "application/json",
            serde_json::to_vec(&request).expect("request JSON"),
        )
        .await;
        let mut context = crate::context::RequestContext::new();

        super::handle_ai_proxy(
            &mut session,
            &config,
            &crate::pipeline::CompiledPipeline::default(),
            "ai.test",
            &mut context,
            None,
        )
        .await
        .expect("aliased request dispatches");
        drop(session);

        let response = live_downstream_body(client).await;
        assert!(response.starts_with(b"HTTP/1.1 200"), "{response:?}");
        assert_eq!(
            pinned_hits.load(Ordering::SeqCst),
            1,
            "the alias must steer the request to the provider it names"
        );
        assert_eq!(
            default_hits.load(Ordering::SeqCst),
            0,
            "round-robin's first provider must not serve a pinned alias"
        );

        let upstream_request = captured.await.expect("capturing upstream task");
        let text = String::from_utf8(upstream_request).expect("upstream request is UTF-8");
        let body = text.split_once("\r\n\r\n").expect("upstream body").1;
        let body: serde_json::Value = serde_json::from_str(body).expect("upstream JSON body");
        assert_eq!(
            body["model"], "gpt-4o-mini-2024-07-18",
            "the alias resolves first, then the selected provider's model_map renames it"
        );
    }

