    /// The bundle half of [`pipeline_with_ai_javascript`], for a test
    /// that needs the chain on a pipeline compiled from real config
    /// (origins, tenants, and `decision_audit` scoping) instead of on
    /// `Default::default()`, which carries none of them and so publishes
    /// no audit record at all.
    fn ai_chain_fixture(manifest: &str, javascript: &str) -> (TempDir, AiExtensionChain) {
        let directory = TempDir::new().expect("extension fixture directory");
        let bundle = directory.path().join("fixture");
        std::fs::create_dir(&bundle).expect("create extension fixture");
        std::fs::write(bundle.join("bundle.yaml"), manifest).expect("write extension manifest");
        std::fs::write(bundle.join("entry.js"), javascript).expect("write extension program");
        let registry = DynamicBundleRegistry::load(
            &ExtensionBundlesConfig {
                bundles_dir: Some(directory.path().display().to_string()),
                sources: Vec::new(),
                grants: Default::default(),
            },
            directory.path(),
            &BTreeSet::new(),
        )
        .expect("load extension fixture");
        let chain =
            AiExtensionChain::from_registry(registry.as_ref()).expect("prepare AI extension chain");
        (directory, chain)
    }

    struct DenyingBufferedPolicy;

    impl sbproxy_plugin::PolicyEnforcer for DenyingBufferedPolicy {
        fn policy_type(&self) -> &'static str {
            "buffered_deny_fixture"
        }

        fn enforce(
            &self,
            _req: &http::Request<bytes::Bytes>,
            _ctx: &mut dyn std::any::Any,
        ) -> std::pin::Pin<
            Box<
                dyn std::future::Future<
                        Output = sbproxy_plugin::PluginResult<sbproxy_plugin::PolicyDecision>,
                    > + Send
                    + '_,
            >,
        > {
            Box::pin(async {
                Ok(sbproxy_plugin::PolicyDecision::Deny {
                    status: 403,
                    message: "buffered policy denied".to_string(),
                })
            })
        }
    }

    fn buffered_deny_metadata() -> sbproxy_modules::DynamicHookMetadata {
        sbproxy_modules::DynamicHookMetadata::new(
            "fixture-bundle",
            "buffered_deny_fixture",
            sbproxy_config::BundleRuntime::Wasm,
            sbproxy_config::BundleBodyMode::Buffered,
            8192,
            sbproxy_config::FailureMode::Closed,
        )
    }

    fn pipeline_with_buffered_deny_policy() -> crate::pipeline::CompiledPipeline {
        let config = sbproxy_config::compile_config(
            r#"
origins:
  "ai.test":
    action:
      type: static
      body: unused
"#,
        )
        .expect("fixture config");
        let mut pipeline =
            crate::pipeline::CompiledPipeline::from_config(config).expect("fixture pipeline");
        pipeline.enforcers = vec![vec![crate::builtin_enforcers::CompiledEnforcer {
            surface: sbproxy_observe::events::PolicySurface::Plugin,
            engine: sbproxy_observe::decision::DecisionEngine::Wasm,
            enforcer: Box::new(DenyingBufferedPolicy),
            dynamic_hook: Some(buffered_deny_metadata()),
            shared_admission: None,
        }]];
        pipeline
    }

